namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    Task<IReadOnlyList<Department>> GetDepartmentsAsync();
    Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null);
    Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseByIdAsync(int id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using C#. Students learn variables, control flow, object-oriented design, and basic data structures.",
            Credits = 4, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has over 15 years of teaching experience and specializes in programming pedagogy and software engineering education.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS 301", Title = "Data Structures & Algorithms",
            Description = "A deep dive into fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Marcus Rivera", InstructorBio = "Dr. Rivera's research focuses on algorithm optimization and competitive programming. He has coached national ICPC teams.",
            IsFeatured = true
        },
        new()
        {
            Id = 3, CourseCode = "CS 420", Title = "Machine Learning",
            Description = "Covers supervised and unsupervised learning, neural networks, support vector machines, and practical applications using Python and scikit-learn.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma leads the university's AI research lab and has published over 40 papers in top-tier machine learning conferences.",
            IsFeatured = false
        },
        new()
        {
            Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra",
            Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an award-winning educator whose research bridges pure mathematics and data science applications.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH 301", Title = "Probability & Statistics",
            Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world applications.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim specializes in applied statistics and has consulted for major healthcare and technology organizations.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments reinforcing lecture material.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, DepartmentName = "Physics",
            InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is a former NASA researcher who brings real-world physics applications into the classroom.",
            IsFeatured = true
        },
        new()
        {
            Id = 7, CourseCode = "PHYS 305", Title = "Quantum Mechanics",
            Description = "Wave-particle duality, Schrödinger equation, quantum states, operators, and applications to atomic and molecular systems.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, DepartmentName = "Physics",
            InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov's groundbreaking research in quantum computing has been featured in Nature and Science magazines.",
            IsFeatured = false
        },
        new()
        {
            Id = 8, CourseCode = "ENG 201", Title = "Creative Writing",
            Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop their voice through weekly writing exercises and peer critique.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 4, DepartmentName = "English",
            InstructorName = "Prof. Diana Hughes", InstructorBio = "Prof. Hughes is a published novelist and poet whose works have appeared in The New Yorker and literary anthologies worldwide.",
            IsFeatured = false
        },
        new()
        {
            Id = 9, CourseCode = "ENG 310", Title = "Shakespeare & Renaissance Literature",
            Description = "In-depth study of Shakespeare's major plays and sonnets in the context of Renaissance culture, theater, and literary tradition.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", DepartmentId = 4, DepartmentName = "English",
            InstructorName = "Dr. William Okafor", InstructorBio = "Dr. Okafor is a Shakespearean scholar who has directed university productions and published extensively on early modern drama.",
            IsFeatured = false
        },
        new()
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "A survey of major civilizations, cultural exchanges, and turning points in human history from ancient times through the late medieval period.",
            Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History",
            InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez specializes in comparative world history and has led archaeological field studies in Mesoamerica and the Mediterranean.",
            IsFeatured = false
        },
    ];

    public Task<IReadOnlyList<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult<IReadOnlyList<Department>>(Departments);
    }

    public Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult<IReadOnlyList<Course>>(query.ToList());
    }

    public Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult<IReadOnlyList<Course>>(Courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));
    }
}

