@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Details")</PageTitle>

@if (course is null)
{
    <p><em>Loading course details...</em></p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.CourseCode &mdash; @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@course.Description</p>

            <h2>Schedule</h2>
            <p>@course.Schedule</p>

            <h2>Credits</h2>
            <p><strong>@course.Credits</strong> credit hours</p>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.InstructorName</h6>
                    <p class="card-text">@course.InstructorBio</p>
                </div>
            </div>

            <div class="mt-3">
                <a href="enroll?courseId=@course.Id" class="btn btn-primary w-100">Enroll in This Course</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override async Task OnInitializedAsync()
    {
        course = await CatalogService.GetCourseByIdAsync(Id);
    }
}

toolArgs.new_str:
@page "/"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the course catalog. Browse departments, explore courses, and submit your enrollment request.</p>

<h2>Featured Courses</h2>

@if (featuredCourses is null)
{
    <p><em>Loading...</em></p>
}
else
{
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text">@course.Credits credits &middot; @course.DepartmentName</p>
                        <a href="courses/@course.Id" class="card-link">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<h2 class="mt-4">Departments</h2>

@if (departments is null)
{
    <p><em>Loading...</em></p>
}
else
{
    <div class="list-group">
        @foreach (var dept in departments)
        {
            <a href="courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
                <strong>@dept.Abbreviation</strong> &mdash; @dept.Name
            </a>
        }
    </div>
}

@code {
    private IReadOnlyList<UniversityCourseCatalog.Models.Course>? featuredCourses;
    private IReadOnlyList<UniversityCourseCatalog.Models.Department>? departments;

    protected override async Task OnInitializedAsync()
    {
        featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        departments = await CatalogService.GetDepartmentsAsync();
    }
}

toolArgs.file_text:
@page "/enroll"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive confirmation via your university email.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseName</strong> has been received. You will be notified of your enrollment status within 2 business days.</p>
        <hr>
        <p class="mb-0"><a href="courses">Browse more courses</a> or <a href="enroll">submit another request</a>.</p>
    </div>
}
else
{
    <EditForm Model="model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="fullName" class="form-label">Full Name</label>
            <InputText id="fullName" class="form-control" @bind-Value="model.FullName" />
            <ValidationMessage For="() => model.FullName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., CS123456" />
            <ValidationMessage For="() => model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                <option value="0">-- Select a course --</option>
                @if (courses is not null)
                {
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.CourseCode - @course.Title</option>
                    }
                }
            </InputSelect>
            <ValidationMessage For="() => model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<UniversityCourseCatalog.Models.Course>? courses;
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        courses = await CatalogService.GetCoursesAsync();

        if (CourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = CourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        var course = await CatalogService.GetCourseByIdAsync(model.CourseId);
        selectedCourseName = course is not null ? $"{course.CourseCode} - {course.Title}" : "the selected course";
        submitted = true;
    }
}

